{
        (void) ed;  /* unused */
        if ((e->size >= 8) && !memcmp (e->data, "AOC", 4)) {
                if (((e->data[4] == 'I') && (e->data[5] == 'I')) ||
                    ((e->data[4] == 'M') && (e->data[5] == 'M')))
                        return pentaxV3;
                else
                        /* Uses Casio v2 tags */
                        return pentaxV2;
        }

